package cl.eventpass.events.controller;
import cl.eventpass.events.model.Event; import cl.eventpass.events.model.EventReservation; import cl.eventpass.events.repository.EventRepository; import cl.eventpass.events.repository.ReservationRepository; import cl.eventpass.events.security.TokenSupport;
import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/events") public class EventController {
 private final EventRepository repo; private final ReservationRepository reservations; public EventController(EventRepository repo,ReservationRepository reservations){this.repo=repo;this.reservations=reservations;}
 public record EventRequest(@NotBlank String name,@NotBlank String location,@NotNull java.time.LocalDateTime eventDate,@Min(1) int capacity){}
 @GetMapping public List<Event> list(HttpServletRequest r){TokenSupport.claims(r);return repo.findAll();}
 @GetMapping("/{id}") public Event get(@PathVariable Long id,HttpServletRequest r){TokenSupport.claims(r);return find(id);}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) public Event create(@Valid @RequestBody EventRequest x,HttpServletRequest r){TokenSupport.require(r,"STAFF");return repo.save(new Event(x.name(),x.location(),x.eventDate(),x.capacity()));}
 @PutMapping("/{id}") @Transactional public Event update(@PathVariable Long id,@Valid @RequestBody EventRequest x,HttpServletRequest r){TokenSupport.require(r,"STAFF");Event e=find(id);try{e.update(x.name(),x.location(),x.eventDate(),x.capacity());return repo.save(e);}catch(IllegalArgumentException ex){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,ex.getMessage());}}
 @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id,HttpServletRequest r){TokenSupport.require(r,"STAFF");repo.delete(find(id));}
 @PostMapping("/internal/{id}/reserve") @Transactional public ResponseEntity<?> reserve(@PathVariable Long id,@RequestParam int quantity,@RequestParam Long orderId){if(quantity<1||orderId==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"quantity y orderId requeridos");var old=reservations.findByOrderId(orderId);if(old.isPresent()){var r=old.get();if(r.getEventId().equals(id)&&r.getQuantity()==quantity)return ResponseEntity.noContent().build();throw new ResponseStatusException(HttpStatus.CONFLICT,"orderId ya reservado con otros datos");}int changed=repo.reserve(id,quantity);if(changed==1){reservations.save(new EventReservation(orderId,id,quantity));return ResponseEntity.noContent().build();}if(!repo.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Evento no encontrado");throw new ResponseStatusException(HttpStatus.CONFLICT,"Aforo insuficiente");}
 private Event find(Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Evento no encontrado"));}
}
